args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?later ?laterLabel ?bd_later ?bd_earlier WHERE {
  dbr:Lisbeth_Cathrine_Amalie_Rose (dbo:birthDate|dbp:birth_date) ?ld .
  dbr:Princess_Raiyah_bint_Hussein (dbo:birthDate|dbp:birth_date) ?rd .
  BIND(xsd:date(?ld) AS ?bd1) .
  BIND(xsd:date(?rd) AS ?bd2) .
  {
    FILTER (?bd1 > ?bd2) .
    BIND(dbr:Lisbeth_Cathrine_Amalie_Rose AS ?later) .
    BIND(?bd1 AS ?bd_later) .
    BIND(?bd2 AS ?bd_earlier) .
  } UNION {
    FILTER (?bd2 > ?bd1) .
    BIND(dbr:Princess_Raiyah_bint_Hussein AS ?later) .
    BIND(?bd2 AS ?bd_later) .
    BIND(?bd1 AS ?bd_earlier) .
  }
  OPTIONAL { ?later rdfs:label ?laterLabel . FILTER(lang(?laterLabel) = 'en') }
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>

SELECT ?person ?abstract WHERE {
  VALUES ?person { dbr:Lisbeth_Cathrine_Amalie_Rose dbr:Princess_Raiyah_bint_Hussein }
  ?person dbo:abstract ?abstract .
  FILTER(lang(?abstract) = 'en')
}

